"""Strict xfails generated by ``pysidtracker.pathdiff`` (the ``oracle`` marker).

Each case in ``_support/pathdiff_xfails.json`` is a representative tune of one
fix in the minimum cover of the HVSC survey's divergences, comparing
:class:`pydefmon.DefmonPlayer` (``format:defmon``) with the sidtrace oracle.
It fails with whydiff's explanation until the fix lands, then passes and the
strict xfail fails the run until the case is pruned (see docs/usage.md).
"""

from pathlib import Path

import pytest

from pysidtracker.pathdiff import check_case, xfail_params

MANIFEST = Path(__file__).resolve().parent / "_support" / "pathdiff_xfails.json"


@pytest.mark.oracle
@pytest.mark.parametrize("case", xfail_params(MANIFEST))
def test_pathdiff(case):
    check_case(case)
